    for (size_t i = 0; i < nblocks; i++) transform(st, data + (i<<6));
    uint8_t block[64];
    size_t rem = len & 63;
    memcpy(block, data + (nblocks<<6), rem);
    block[rem] = 0x80;
    if (rem >= 56) {
        memset(block+rem+1, 0, 63-rem);
        transform(st, block);
        memset(block, 0, 56);
    } else {
