#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <openssl/sha.h>

/* From openssl perlasm:
   typedef struct { void *ptr; int blocks; } HASH_DESC;
   void sha256_multi_block(SHA256_CTX *ctx, HASH_DESC *inp, int num);
   ctx holds 8 streams of state? Disassembly:
     leaq 0x80(%rdi), %rdi   then loads 8 xmm from -0x80(%rdi) ... +0x60
   So rdi points at a structure whose hash state starts at offset 0, 8 xmm = 128 bytes
   of transposed? It loads xmm8 from -0x80(rdi_after) i.e. original rdi+0.
   8 xmmwords = 128 bytes = 8 state words * 4 lanes * 4 bytes. Yes: state is
   stored as 8 vectors of 4 lanes (A0 A1 A2 A3, B0..).
   inp: 4 descriptors of 16 bytes: ptr at 0, blocks (int) at 8.
   num in edx is saved but the SSE path seems to always do 4 streams (r8..r11).
*/

typedef struct {
    const unsigned char *ptr;
    int blocks;
    int pad;
} HASH_DESC;

/* state layout: 8 x __m128i, each holding one state word across 4 lanes.
   We pass a buffer of 8*16 = 128 bytes, but the function does leaq 0x80(%rdi)
   and then reads -0x80 .. +0x60, i.e. exactly [rdi, rdi+128). Good.
   Also it writes results back — need to check. For a probe, init and compare. */

extern void sha256_multi_block(void *ctx, const HASH_DESC *inp, int num);

static void store_state(uint32_t st[8][4], uint8_t *ctx) {
    /* each state word is an xmm: lanes 0..3 */
    for (int w = 0; w < 8; w++) {
        memcpy(ctx + w*16, st[w], 16);
    }
}
static void load_state(uint8_t *ctx, uint32_t st[8][4]) {
    for (int w = 0; w < 8; w++) memcpy(st[w], ctx + w*16, 16);
}

int main() {
    /* 2 blocks of known data per lane */
    unsigned char msg[4][128];
    for (int l = 0; l < 4; l++) {
        for (int i = 0; i < 128; i++) msg[l][i] = (unsigned char)(l*17 + i);
    }
    uint32_t iv[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,
                      0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    uint32_t st[8][4];
    for (int w = 0; w < 8; w++) for (int l = 0; l < 4; l++) st[w][l] = iv[w];

    uint8_t ctx[128] __attribute__((aligned(64)));
    memset(ctx, 0, sizeof(ctx));
    store_state(st, ctx);

    HASH_DESC desc[4];
    for (int l = 0; l < 4; l++) {
        desc[l].ptr = msg[l];
        desc[l].blocks = 2;
        desc[l].pad = 0;
    }

    sha256_multi_block(ctx, desc, 4); /* num meaning unknown; SSE path ignores? */
    load_state(ctx, st);

    /* reference: SHA256_Transform twice */
    for (int l = 0; l < 4; l++) {
        SHA256_CTX c;
        SHA256_Init(&c);
        SHA256_Update(&c, msg[l], 128);
        /* SHA256_Update of 128 bytes = exactly 2 blocks, no padding yet, state in c.h */
        int ok = 1;
        for (int w = 0; w < 8; w++) if (c.h[w] != st[w][l]) ok = 0;
        printf("lane %d match %d\n", l, ok);
        if (!ok) {
            printf("  ref:");
            for (int w = 0; w < 8; w++) printf(" %08x", c.h[w]);
            printf("\n  got:");
            for (int w = 0; w < 8; w++) printf(" %08x", st[w][l]);
            printf("\n");
        }
    }
    return 0;
}
EOF
