#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>
#include <openssl/sha.h>

typedef struct { const unsigned char *ptr; int blocks; int pad; } HASH_DESC;
extern void sha256_multi_block(void *ctx, const HASH_DESC *inp, int num);

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

int main() {
    size_t n = 20000ull * 1024;
    size_t nblocks = n >> 6; /* ignore tail for throughput */
    unsigned char *msg[8];
    for (int l = 0; l < 8; l++) {
        msg[l] = malloc(nblocks * 64);
        memset(msg[l], 0x20 + l, nblocks * 64);
    }
    uint32_t iv[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,
                      0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    uint8_t ctx[256] __attribute__((aligned(64)));
    HASH_DESC desc[8];

    /* chunk into groups of blocks so the int counter stays in range.
       nblocks for 20MB is 327680, fits in signed 32-bit (2e9). OK. */
    double t0 = now();
    int reps = 3;
    for (int r = 0; r < reps; r++) {
        for (int w = 0; w < 8; w++)
            for (int l = 0; l < 8; l++) {
                uint32_t v = iv[w];
                memcpy(ctx + w*32 + l*4, &v, 4);
            }
        for (int l = 0; l < 8; l++) {
            desc[l].ptr = msg[l];
            desc[l].blocks = (int)nblocks;
            desc[l].pad = 0;
        }
        sha256_multi_block(ctx, desc, 8);
    }
    double t1 = now();
    double ms = (t1 - t0) / reps * 1000;
    double mb = 8.0 * nblocks * 64 / 1e6;
    printf("multi x8: %.2f ms for %.1f MB (%.0f MB/s)  per-stream %.2f ms\n",
           ms, mb, mb / (ms/1000.0), ms); 
    /* per-stream time is ms if we wanted 8 independent hashes; for ONE hash we only have 1 stream.
       Throughput per stream = total_MB/8 / time. */
    printf("per-stream equivalent: %.2f ms for %.1f MB\n", ms, (nblocks*64)/1e6);

    uint8_t out[32];
    t0 = now();
    for (int r = 0; r < reps; r++) SHA256(msg[0], nblocks*64, out);
    t1 = now();
    ms = (t1-t0)/reps*1000;
    printf("openssl x1: %.2f ms for %.1f MB (%.0f MB/s)\n", ms, (nblocks*64)/1e6, ((nblocks*64)/1e6)/(ms/1000));

    /* correctness on a small full hash including that multi_block state matches transform */
    for (int l = 0; l < 8; l++) free(msg[l]);
    return 0;
}
