{"command":"cat > mb_one.c << 'EOF'
#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>
#include <openssl/sha.h>

typedef struct { const unsigned char *ptr; int blocks; int pad; } HASH_DESC;
extern void sha256_multi_block(void *ctx, const HASH_DESC *inp, int num);

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

/* Hash one message using 8-way multi_block by feeding the same message? 
   That doesn't help a single chain. This measures overhead of the call path
   we'd use if we had 8 messages. For a SINGLE message, multi_block cannot
   speed the chain. Confirm by hashing 8 copies and dividing. */

int main() {
    size_t n = 20000ull * 1024;
    unsigned char *data = malloc(n + 128);
    memset(data, 0xab, n);

    uint8_t out[32];
    double t0 = now();
    for (int i = 0; i < 5; i++) SHA256(data, n, out);
    double t1 = now();
    printf("SHA256 one-shot: %.2f ms\n", (t1-t0)/5*1000);

    SHA256_CTX c;
    t0 = now();
    for (int i = 0; i < 5; i++) {
        SHA256_Init(&c);
        SHA256_Update(&c, data, n);
        SHA256_Final(out, &c);
    }
    t1 = now();
    printf("SHA256_Init/Update/Final: %.2f ms\n", (t1-t0)/5*1000);

    /* large single Update vs many small */
    t0 = now();
    for (int i = 0; i < 3; i++) {
        SHA256_Init(&c);
        size_t off = 0;
        while (off < n) {
            size_t chunk = 64 * 1024;
            if (off + chunk > n) chunk = n - off;
            SHA256_Update(&c, data + off, chunk);
            off += chunk;
        }
        SHA256_Final(out, &c);
    }
    t1 = now();
    printf("64KB updates: %.2f ms\n", (t1-t0)/3*1000);

    free(data);
    return 0;
}
EOF
cc -O2 -I/usr/local/opt/openssl@3/include -L/usr/local/opt/openssl@3/lib mb_one.c -lcrypto -o mb_one && ./mb_one"}
